def calculate_discount(price, is_vip):
    # Common logic bug: VIPs get 20%, others get 10%
    rate = 0.20 if is_vip else 0.10
    return price * (1 - rate)

print("VIP price for $100:", calculate_discount(100, True))

def find_average(nums):
    print(f"DEBUG: Received {nums=}, type={type(nums)}")
    if not nums:
        return 0
    return sum(nums) / len(nums)

print("Average:", find_average([10, 20, 30]))

# Clean isolated verification
def safe_get(d, key):
    # Defensive check avoids KeyError
    return d.get(key, "N/A")

print(safe_get({"name": "Kim"}, "role"))

